    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil00401.tx_fn_selectComplate" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/submission/searchDisclosureDocument.do",
        ref: "dma_loadListReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil00401.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_127").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_docPageList_fmt_column7
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_docPageList_fmt_column7 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "disclsAcptTpCd") ?? '') : '');
        if (v === 'F') { return "최초문서"; }
        if (v === 'M') { return "본문정정"; }
        if (v === 'U') { return "첨부정정"; }
        if (v === 'A') { return "첨부추가"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column7" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.grd_docPageList_fmt_column8
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_docPageList_fmt_column8 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "langTpCd") ?? '') : '');
        if (v === '0') { return "국문"; }
        if (v === '1') { return "영문"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column8" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.grd_docPageList_fmt_submitNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_docPageList_fmt_submitNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "wrtrptMaindocTpCd") ?? '') : '');
        if (v === '1') { return String((dl && dl.getCellData ? dl.getCellData(r, "submitNm") : '') ?? ''); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.submitNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.setAllValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setAllValue = function () {
    /* sdd-asis-lifecycle:begin setAllValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const chkObj = document.getElementsByName('selDiscls');
    for (let i = 0; i < chkObj.length; i++) {
        scwin.checkIt(chkObj[i]);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkDocSubmitTp
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkDocSubmitTp = async function () {
    /* sdd-asis-lifecycle:begin checkDocSubmitTp — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const docSubmitTp = 'null';
    if (docSubmitTp === '1') {
        await $c.win.alert('이미 제출 완료된 보고서 입니다.');
    } else {
        if (docSubmitTp === '2') {
            await $c.win.alert('이미 제출 삭제된 보고서 입니다.');
        } else {
            if (docSubmitTp === '0') {
                await $c.win.alert('정상 삭제되었습니다.');
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchList = async function () {
    /* sdd-asis-lifecycle:begin fn_searchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('cal_searchBeginDd').getValue()> $c.util.getComponent('cal_searchEndDd').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    await scwin.tx_fn_searchList();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteDeleteReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param applNo
 * @returns
 * @hidden N
*/
scwin.deleteDeleteReq = async function (applNo) {
    /* sdd-asis-lifecycle:begin fn_delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await $c.win.confirm('삭제하시겠습니까?')) {
        (document.searchForm || { elements: [] }).action = "/submission/searchDisclosureDocument.do?method=removeWritingDocument";
        $c.util.getComponent('dma_deleteReq').set('applNo', applNo);
        await scwin.tx_fn_delete();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkIt
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.checkIt = function (ver) {
    /* sdd-asis-lifecycle:begin checkIt — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.obj = (document.deleteform || { elements: [] });
    let tmpVal = null;
    let arrLength = 0;
    const arrNo = ((ver.value).split("|"))[0];
    scwin.resetRtnVal(arrNo);
    if (scwin.chkArrNo.length != 0) {
        arrLength = scwin.chkArrNo.length;
    }
    if (ver.checked === true) {
        tmpVal = (ver.value).split("|");
        scwin.chkArrNo[arrLength] = tmpVal[0];
        scwin.chkTitle[arrLength] = tmpVal[1];
    }
    rtnVal = scwin.chkArrNo.join(",") + "|" + scwin.chkTitle.join(",");
    (($c.util.getComponent("txt_docs")) && ($c.util.getComponent("txt_docs")).setValue ? ($c.util.getComponent("txt_docs")).setValue(scwin.chkTitle.join("<br/>")) : (($c.util.getComponent("txt_docs")) ? (($c.util.getComponent("txt_docs")).innerHTML = scwin.chkTitle.join("<br/>")) : void (scwin.chkTitle.join("<br/>"))));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.resetRtnVal
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.resetRtnVal = function (ver) {
    /* sdd-asis-lifecycle:begin resetRtnVal — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const tmpArr1 = new Array(0);
    const tmpArr2 = new Array(0);
    let cnt = 0;
    for (let i = 0; i < scwin.chkArrNo.length; i++) {
        if (scwin.chkArrNo[i] !== ver) {
            tmpArr1[cnt] = scwin.chkArrNo[i];
            tmpArr2[cnt] = scwin.chkTitle[i];
            cnt++;
        }
    }
    scwin.chkArrNo = new Array(0);
    scwin.chkTitle = new Array(0);
    scwin.chkArrNo = tmpArr1;
    scwin.chkTitle = tmpArr2;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = async function () {
    /* sdd-asis-lifecycle:begin fn_close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await $c.win.confirm('공시 삭제를 종료하시겠습니까?')) {
        $c.win.closePopup();
    }
    /* sdd-asis-lifecycle:end */
};


